-- Zumba fitness: party verze fotky na přání studia (17. 11. 2026) – šest žen různého věku a postavy dělá stejný krok
-- (ruka nahoře, druhá v bok), každá trochu po svém, pod žlutým, zeleným a bílým reflektorem. Nahrazuje fotku z migrace 0164.
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data") VALUES
  ('8865815d-7f3d-47b7-a7f6-7320a2bff231', 'zumba-fitness-party.webp', 'image/webp', 1600, 900, 120488, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
-- …u lekce místo fotky z 0164 (nebo té úplně původní) – jen dokud ji studio nevyměnilo za vlastní.
UPDATE "class_types" SET "image_url" = '/media/8865815d-7f3d-47b7-a7f6-7320a2bff231.webp'
WHERE "slug" = 'zumba-fitness' AND "image_url" IN ('/media/c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2.webp', '/media/aef42593-3d7b-4d26-a6e6-07ee2d001857.webp')
  AND EXISTS (SELECT 1 FROM "media" WHERE "id" = '8865815d-7f3d-47b7-a7f6-7320a2bff231');
--> statement-breakpoint
-- Vytvořená pomocí AI jako ty předchozí: stejné označení (vodoznak chobotnice s „AI“), pokud ho měly.
UPDATE "settings" SET "value" = (SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT jsonb_array_elements_text("value" || '["/media/8865815d-7f3d-47b7-a7f6-7320a2bff231.webp"]'::jsonb) x) s)
WHERE "key" = 'aiImages' AND jsonb_typeof("value") = 'array' AND ("value" ? '/media/c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2.webp' OR "value" ? '/media/aef42593-3d7b-4d26-a6e6-07ee2d001857.webp') AND NOT "value" ? '/media/8865815d-7f3d-47b7-a7f6-7320a2bff231.webp';
